try {
  const stdout = $input.first().json.stdout || '';
  const data = JSON.parse(stdout);

  if (!data || data.length === 0) {
    return [];
  }

  return data.map(item => ({ json: item }));
} catch (error) {
  console.log('Parse error:', error);
  return [];
}

const p = $json.platform || 'unknown';
const emoji = {'cian': '🔵', 'yandex': '🔴', 'avito': '🟢'}[p] || '⚪';
const name = {'cian': 'Cian.ru', 'yandex': 'Yandex.Realty', 'avito': 'Avito.ru'}[p] || p;

const rooms = $json.rooms === 0 ? 'Студия' : ($json.rooms ? `${$json.rooms}-комн` : '');
const price = $json.price ? `${Math.round($json.price).toLocaleString('ru-RU')} ₽/мес` : 'Цена не указана';

let msg = `${emoji} *${name}*\n\n*${$json.title}*\n\n💰 ${price}\n`;
if (rooms) msg += `🏠 ${rooms}`;
if ($json.area) msg += `${rooms ? ', ' : ''}${$json.area} м²`;
msg += '\n';
if ($json.address) msg += `📍 ${$json.address}\n`;
if ($json.phone) msg += `📞 \`${$json.phone}\`\n`;
msg += `\n🔗 [Открыть](${$json.url})`;

return { json: { ...$json, message: msg }};
